    {
      "statement": "Selecting the highest version and then the greatest updated_timestamp for each email_template_id is an acceptable replacement for filtering metadata by is_most_recent_version.",
      "about": "requirement",
      "target": "marts.marketo__email_templates",
      "evidence_of_dependence": "ROW_NUMBER() OVER (PARTITION BY email_template_id ORDER BY version DESC, updated_timestamp DESC) AS version_rank ... WHERE t.version_rank = 1",
      "alternative": "The contract says to \"keep only rows marked as the most recent version\"; the new code ignores that flag and emits \"TRUE AS is_most_recent_version\".",
      "importance": 4,
      "reason": "The replacement can select different template metadata or include templates with no marked current version.",
      "updates": "c6-6"
    },
    {
      "statement": "Rows tied for the highest version and updated_timestamp within an email_template_id have identical output metadata.",
      "about": "data",
      "target": "marts.marketo__email_templates",
      "evidence_of_dependence": "ROW_NUMBER() OVER (PARTITION BY email_template_id ORDER BY version DESC, updated_timestamp DESC)",
      "alternative": null,
      "importance": 2,
      "reason": "Conflicting tied rows would make the selected template metadata arbitrary.",
      "updates": null
    },
